"""Aggregate executed Phase 4 evidence. Fails closed on incomplete/failing reports."""
import argparse,hashlib,json,re,shutil
from pathlib import Path

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--validation',type=Path,required=True);ap.add_argument('--work-reports',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);a=ap.parse_args();root=Path(__file__).resolve().parent;v=a.validation;out=a.output;out.mkdir(parents=True,exist_ok=True);reports=v/'reports';manifest=json.loads((v/'tested/ICARUS_SOL_Command_Interface_Phase4_Lite/BUILD_MANIFEST.json').read_text());runtime=manifest['runtime_files']
 assert len(runtime)==65
 for n,h in runtime.items():assert hashlib.sha256((root/n).read_bytes()).hexdigest()==h,(n,'Runtime changed after extraction')
 suites={}
 for n,count in [('cinematic',71),('stability',30),('compatibility',44),('interface',17),('production',2),('bridge',3)]:
  r=json.loads((reports/(n+'.json')).read_text());assert r['passed'] and r['tests_run']==count and not r['errors'] and not r['failures'],n;suites[n]={'passed':True,'executions':count}
 node=(reports/'node.txt').read_text();assert re.search(r'tests 265\b',node) and re.search(r'pass 265\b',node) and re.search(r'fail 0\b',node)
 for n,count in [('mobile_functional',15),('tablet_touch',11)]:
  r=json.loads((reports/(n+'.json')).read_text());assert r['passed'] and len(r['checks'])==count and not r['errors'];suites[n]={'passed':True,'checks':count,'limits':r.get('limits',r.get('limit'))}
 static=json.loads((reports/'static.json').read_text());assert static['passed'];inventory=json.loads((a.work_reports/'control_inventory.json').read_text());assert not inventory['missing_ids'] and inventory['unchanged_world_during_full_inventory'];assert len(inventory['existing_controls'])==106
 migrations={}
 for n in ['phase1','phase2','phase3','phase3_loss','phase35']:
  r=json.loads((reports/('migrate_'+n+'.json')).read_text());assert r['passed'] and not r['errors'] and not r['mismatched_import_domains'] and not r['mismatched_reload_domains'];assert r['memorials_after']==r['memorials_before'];migrations[n]={k:r[k] for k in ['imported_history_records','imported_tick','resumed_tick','crew_before','crew_after','memorials_after','import_seconds','elapsed_seconds']}
 assert migrations['phase3_loss']['crew_after']==19 and migrations['phase3_loss']['memorials_after']==['Nadia Kline']
 campaigns=json.loads((a.work_reports/'campaign_summary.json').read_text());assert campaigns['passed'] and set(campaigns['campaigns'])=={'normal_1001','compound_4807'}
 for n,c in campaigns['campaigns'].items():assert c['passed'] and not c['public_source_audit_errors'] and c['runtime_sha256']==runtime,n
 testhash={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(root.glob('test_*')) if p.is_file()}
 accepted={'automated_scope_passed':True,'full_phase4_complete':False,'final_release_ready':False,'runtime_from_commit':'d39f2d70f8cae7599bcf4705f4d846116502373c','tested_extracted_manifest_source':manifest['source_commit'],'runtime_files':runtime,'node':{'passed':265,'failed':0,'skipped':0},'browser_executions':sum(x['executions'] for x in suites.values() if 'executions' in x),'suites':suites,'control_inventory':{'baseline_id_controls':106,'missing':[],'visibly_reached_id_controls':len(inventory['reachable_ids']),'world_unchanged_during_inspection':True},'migrations':migrations,'campaigns':['compound_4807','normal_1001'],'test_source_sha256':testhash,'unverified_gates':['Physical Windows installation/desktop input','Physical Tab S5e/Android/Wi-Fi','Physical Samsung TV','Antivirus engine scan (clamscan/Defender unavailable)','Screen reader and sustained human usability/content/contrast review'],'evidence_policy':'Only completed final-runtime reports are accepted. Earlier source/package runs and aborted initial campaign are diagnostics. Counts overlap inherited scenarios. Emulation and stubbed host I/O are not hardware certification.'}
 (out/'accepted_summary.json').write_text(json.dumps(accepted,indent=2));shutil.copy(a.work_reports/'campaign_summary.json',out/'campaign_summary.json');shutil.copy(a.work_reports/'control_inventory.json',out/'control_inventory.json')
 for p in reports.glob('*'):
  if p.suffix in ['.json','.txt']:shutil.copy(p,out/p.name)
 (out/'campaigns').mkdir(exist_ok=True)
 for p in (a.work_reports/'accepted_campaigns').glob('*/campaign_*.json'):shutil.copy(p,out/'campaigns'/(p.parent.name+'.json'))
 (out/'screenshots').mkdir(exist_ok=True)
 for p in (a.work_reports/'screenshots').glob('*.png'):shutil.copy(p,out/'screenshots'/p.name)
 for name in ['before_home.png','before_operations.png','after_home.png','after_directive_toolbar.png','after_locations.png']:
  if (a.work_reports/name).exists():shutil.copy(a.work_reports/name,out/'screenshots'/name)
 diagnostics=out/'diagnostics';diagnostics.mkdir(exist_ok=True)
 for name in ['command_interface_initial_failures.json','interface_course_fixture_assumption.json']:
  if (a.work_reports/name).exists():shutil.copy(a.work_reports/name,diagnostics/name)
 prior=Path('/workspace/work/phase4_validation/reports')
 for name in ['interface.json','stability.json','cinematic.txt','compatibility.txt']:
  if (prior/name).exists():shutil.copy(prior/name,diagnostics/('superseded_'+name))
 (out/'harness').mkdir(exist_ok=True)
 for name in ['run_suite.py','migrate.py','mobile_functional.py','tablet_touch.py']:shutil.copy(v/name,out/'harness'/name)
 for name in ['test_command_interface.py','test_test_clock.js','unified_soak.py','summarize_refinement_campaigns.py','verify_frontier_backup.py','audit_command_controls.py','generate_command_validation.py','verify_command_package.py','package_command_interface.py']:shutil.copy(root/name,out/'harness'/name)
 text=['# Phase 4 measured validation','','Status: implemented interface batch verified within the following automated scope. **Full Phase 4/final release acceptance remains open** for native hardware, accessibility and sustained human review. No universe or physics-model expansion.','','Runtime frozen at **d39f2d7**, tested through an independent source-based Lite extraction. All **65 runtime file hashes** match both accepted campaigns and final repository source. Later packaging/documentation may change; retained runtime identity is checked again.','','| Suite | Actual result |','| --- | --- |','| Node deterministic | 265 passed, 0 failed/skipped |']
 for n,x in suites.items():text.append('| '+n+' | '+str(x.get('executions',x.get('checks')))+' passed |')
 text+=['','Browser suite executions total '+str(accepted['browser_executions'])+'; inherited cases overlap. Mobile and tablet figures are checks, not native certifications. Real HTTP/Chromium are exercised; desktop input and TV sockets are explicit stubs. Static syntax/dependency/source checks pass; they are not antivirus scanning.','','## Preserved UI and actual clocks','','All 106 original ID controls remain; '+str(len(inventory['reachable_ids']))+' ID controls (including additions) were visibly reached in the paused fixture. Full inspection leaves world state unchanged. Source-backed dynamic field-console families retain their handlers. Screenshots cover 1920×1080, 1280×800 and 1024×768 plus a real touch-emulated tablet flow. Shared straight control geometry and muted gradients are checked beyond one row.','', 'The ordinary page (no deterministic hooks) runs actual TEST 1/5/20×. Tests verify 20 physical minutes per real minute, equal crew/resource progression to normal under a fixed initial seed, per-minute travel fuel burn and real coordinate movement, scoped release without teleportation, pause/resume, normal/holiday restoration, Monday boundary once with the same crew, restart to normal, read-only denial, canceled reset, imported preferences, retained live widget nodes and unique controls after live timer progression. Node cases cover six-hour recovery/work budget and holiday/week invariants.','','## Actual full-backup migrations','','| Donor | Receiving history | Tick | Survivors | Memorials retained |','| --- | --- | --- | --- | --- |']
 for n,x in migrations.items():text.append(f"| {n} | {x['imported_history_records']} | {x['imported_tick']} → {x['resumed_tick']} | {x['crew_after']} | {', '.join(x['memorials_after']) or 'none'} |")
 text+=['','All compared crew/world/research/knowledge/economy domains and supplied history IDs are retained; exact save/reload and resumed audits pass. Historical Nadia Kline death is preserved, never revived. True-v1.3 migration and Core/Extended isolation also pass in the regression suites. Streaming corruption, cancellation, atomic abort, fencing and 4,096-row stream fixture tests pass; the old 45k-stream performance benchmark was not repeated. Backup UI hardening remains deferred.','','## Continuous campaigns','','Fixed start 2026-10-28 00:00 UTC, America/Chicago; hourly real intervals drive production controllers. Test-driver per-tick autosave is disabled, explicit saves/checkpoint reloads asserted. Seven real days equal 25 simulated days; thirty equal 111.75 due to synchronized holidays. The compound initial damage/health profile is an explicit backup-import fixture, not a naturally claimed incident.','','| Profile | Real / simulated days | Alive / dead | Arrivals | Field / local jobs | Cases | Experiments complete / failed / no result | Conversations | Films | History |','| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |']
 for n,c in campaigns['campaigns'].items():
  e=c['experiment_statuses'];text.append(f"| {n} | {c['real_days']} / {c['sim_days']} | {c['alive']} / {len(c['dead'])} | {c['arrivals']} | {c['field_missions']} / {c['local_jobs']} | {c['science_cases']} | {e.get('complete',0)} / {e.get('failed',0)} / {e.get('no_result',0)} | {c['conversations']} | {c['weekly_films']} | {c['history_records']} |")
 text+=['','Every daily resource/frontier/chronicle/knowledge/creature/cinematic audit passes. Full-history audit finds no missing/private public film or SOL sources and no invalid snapshot provenance. Actual travel/objectives are required; survival alone is not the pass criterion. Each campaign uses 1.96245155 travel fuel; no new resource-acquisition quota is imposed. Resource balances, retained frame counts, actual source-kind diversity, film durations and storage growth are in campaign_summary.json. All 20 original identities remain accounted for; weekly archives retain the same world. Natural Legendary eligibility is zero, which is valid.','', 'Normal campaign primary compressed cache grows 350,360 → 1,454,206 bytes; compound 362,334 → 698,092. These are actual compatibility-cache measurements, not constant-memory/save-growth claims. Full history grows and remains retained. The campaign helper retains its legacy 1.7.5 backup-envelope tag; all running assets are identified by the matching 65 Phase 4 hashes. Actual user exports correctly declare 1.8.0-phase4.','','## Corrected / superseded diagnostics','','Retained diagnostics include initial hidden-control/touch-layout checks, obsolete Save navigation/version expectations, and a real accumulating-panel/duplicate-ID defect caught during longer production-page execution. The latter is fixed and guarded by uniqueness after real timer advancement. The initial 30-day run was deliberately stopped after the fix, and the initial 7-day/source-package results are excluded. A new course test initially assumed up-front fuel payment; source inspection confirmed existing per-minute burn, and the corrected test verifies payment and movement after advancing the real clock. No model was changed to satisfy that assumption.','','## Unverified / not run','','Physical Windows installation/input, Tab S5e/Android/Wi-Fi, Samsung TV, Windows Defender/other antivirus engine scan, screen-reader use, native GPU/FPS, sustained human contrast/usability/content review. Chromium emulation does not close those gates. No antivirus protection was disabled. Full Phase 4/final release is **not** declared complete. See PHASE4_UI_LIMITATIONS.md.','']
 content='\n'.join(text);(root/'PHASE4_UI_VALIDATION.md').write_text(content);(out/'VALIDATION.md').write_text(content);print(json.dumps({'accepted':True,'node':265,'browser_executions':accepted['browser_executions'],'migrations':len(migrations),'campaigns':len(campaigns['campaigns']),'full_phase4_complete':False},indent=2))
if __name__=='__main__':main()
